script:
app.beginUndoGroup("Animate Variable Font Axes");
try {
  var comp = app.project.activeItem;
  if (!(comp instanceof CompItem)) {
    throw new Error("Open a composition first.");
  }

  var layer = null;
  var sel = comp.selectedLayers;
  var i;
  for (i = 0; i < sel.length; i++) {
    if (sel[i] instanceof TextLayer) {
      layer = sel[i];
      break;
    }
  }
  if (!layer) {
    throw new Error("Select a text layer first.");
  }

  var textProps = layer.property("ADBE Text Properties");
  var doc = textProps.property("ADBE Text Document").value;

  var fontObj = doc.fontObject;
  if (!fontObj && app.fonts && app.fonts.getFontsByPostScriptName) {
    var matches = app.fonts.getFontsByPostScriptName(doc.font);
    if (matches && matches.length) fontObj = matches[0];
  }
  if (!fontObj || !fontObj.hasDesignAxes || !fontObj.designAxesData) {
    throw new Error("The layer's font has no variable design axes -- apply a variable font first.");
  }

  var rangeByTag = {};
  for (var a = 0; a < fontObj.designAxesData.length; a++) {
    var axisData = fontObj.designAxesData[a];
    rangeByTag[axisData.tag] = { min: axisData.min, max: axisData.max };
  }

  var animators = textProps.property("ADBE Text Animators");
  for (var existing = 1; existing <= animators.numProperties; existing++) {
    if (animators.property(existing).name === "Variable Font Axes") {
      throw new Error("An animator named 'Variable Font Axes' already exists on this layer -- not adding a duplicate.");
    }
  }

  var animator = animators.addProperty("ADBE Text Animator");
  animator.name = "Variable Font Axes";
  var animatorProps = animator.property("ADBE Text Animator Properties");

  if (typeof animatorProps.addVariableFontAxis !== "function") {
    throw new Error("Variable font axis scripting requires After Effects 26.0 or later.");
  }

  var startTime = layer.inPoint;
  var endTime = Math.min(layer.inPoint + 1, layer.outPoint);
  var animatedCount = 0;

  function clamp(value, min, max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
  }

  function animateAxis(tag) {
    var axis;
    try {
      axis = animatorProps.addVariableFontAxis(tag);
    } catch (e) {
      return;
    }
    var range = rangeByTag[tag];
    if (!range) return;
    var target = clamp(axis.value, range.min, range.max);
    var low = clamp(target * 0.5, range.min, range.max);
    if (low >= target) {
      low = range.min;
    }
    axis.setValueAtTime(startTime, low);
    axis.setValueAtTime(endTime, target);
    axis.setInterpolationTypeAtKey(1, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    axis.setInterpolationTypeAtKey(2, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    animatedCount++;
  }

  animateAxis("wght");
  animateAxis("wdth");

  if (animatedCount === 0) {
    throw new Error("The layer's font has neither a weight nor a width axis.");
  }
} finally {
  app.endUndoGroup();
}
